    const mostGap=data.slice(0,3),lost=[...data].sort((a,b)=>a.change-b.change).slice(0,3),gained=[...data].sort((a,b)=>b.change-a.change).slice(0,3);const lead=`Na área selecionada, a Alta tem ${pct(share*100)} de share ponderado; o mercado totalizou ${cash(sum.market)} doses.`;const opportunityText=opportunity?`Os municípios abaixo da média da área somam ${cash(opportunity)} doses de cenário para alcançar essa referência.`:'Não há volume positivo abaixo da referência ponderada dentro do filtro atual.';const marketRead=marketGrowth<0?'O mercado encolheu no período; diferencie retração de mercado de perda de share.':marketGrowth>0?'O mercado cresceu; compare a evolução das doses Alta para ver se a empresa capturou o crescimento.':'Sem referência comparável de mercado anterior.';$('marketInsights').innerHTML=`<div class="market-insight"><b>Área selecionada</b><span>${esc(lead)}</span></div><div class="market-insight"><b>Crescimento do mercado</b><span>${esc(marketRead)} Mercado ${marketGrowth===null?'—':`${marketGrowth>=0?'+':''}${pct(marketGrowth)}`} · Alta ${altaGrowth===null?'—':`${altaGrowth>=0?'+':''}${pct(altaGrowth)}`}.</span></div><div class="market-insight"><b>Onde há maior lacuna estimada</b><span>${mostGap.length?mostGap.map(x=>`${esc(x.m.city)} (${cash(x.opportunity)} doses)`).join(' · '):'Sem municípios comparáveis.'}</span></div><div class="market-insight"><b>Maiores quedas de share</b><span>${lost.filter(x=>x.change<0).length?lost.filter(x=>x.change<0).map(x=>`${esc(x.m.city)} (${pct(x.change*100)} p.p.)`).join(' · '):'Nenhuma queda no ranking atual.'}</span></div><div class="market-insight"><b>Maiores ganhos de share</b><span>${gained.filter(x=>x.change>0).length?gained.filter(x=>x.change>0).map(x=>`${esc(x.m.city)} (+${pct(x.change*100)} p.p.)`).join(' · '):'Nenhum ganho no ranking atual.'}</span></div><div class="market-insight"><b>Competição estimada</b><span>${cash(competitor)} doses ASBIA não Alta na área. ${esc(opportunityText)}</span></div>`;
    $('marketSourceNote').textContent=`Base municipal: ${market.lastMunicipalImport?`${market.lastMunicipalImport.name} · atualizada ${new Date(market.lastMunicipalImport.updatedAt).toLocaleString('pt-BR')} · ${market.lastMunicipalImport.municipalities} municípios`:'09 ASBIA POR MUNICIPIO - JAN.SET.xlsx, base enviada'} · Comparativo: ${market.lastCompareImport?`${market.lastCompareImport.name} · ${market.lastCompareImport.period} · atualizado ${new Date(market.lastCompareImport.updatedAt).toLocaleString('pt-BR')}`:'Setembro 2026 e Jan–Set 2026, arquivos enviados'}.`;
