  function cityKey(city,state){const raw=String(city||'').trim();const m=raw.match(/^(.*?)[\s,-]+([A-Z]{2})\s*$/i),name=m?m[1]:raw,uf=state||m?.[2]||'';return norm(uf)+norm(name)}
  function marketByCode(code){return (market.municipalities||[]).find(m=>String(m.ibge)===String(Math.trunc(num(code))))}
  function mapMarket(city,state,ibge){return marketByCode(ibge)||(()=>{const key=cityKey(city,state);return (market.municipalities||[]).find(m=>cityKey(m.systemName||m.city,m.state)===key||cityKey(m.city,m.state)===key)})()}
  function loadClients(){const records=(()=>{try{return JSON.parse(localStorage.getItem(CRM_KEY)||'[]')}catch{return []}})().filter(allowedRecord),byCode=new Map(),byName=new Map();for(const r of records){if(r.clientCode)byCode.set(norm(r.clientCode),r);byName.set(norm(r.name)+'|'+norm(r.region),r)}const grouped=new Map();for(const t of sales){if(norm(t.districtManager)!==DISTRICT||!regionOk(t.region)||!t.name)continue;const key=norm(t.clientCode)?'c:'+norm(t.clientCode):'n:'+norm(t.name)+'|'+norm(t.region);let c=grouped.get(key);if(!c){c={key,name:t.name,clientCode:t.clientCode||'',region:regionOk(t.region),city:t.city||'',ibge:t.ibge||'',profile:t.profile||'',sales:0,lastBuy:'',record:null,rows:[]};grouped.set(key,c)}c.rows.push(t);if(t.date>=c.lastBuy){c.name=t.name||c.name;c.city=t.city||c.city;c.ibge=t.ibge||c.ibge;c.profile=t.profile||c.profile;c.lastBuy=t.date}c.sales+=Number(t.value)||0}
    for(const c of grouped.values())c.record=(c.clientCode&&byCode.get(norm(c.clientCode)))||byName.get(norm(c.name)+'|'+norm(c.region))||null;
    for(const r of records){const key=norm(r.clientCode)?'c:'+norm(r.clientCode):'n:'+norm(r.name)+'|'+norm(r.region);if(!grouped.has(key))grouped.set(key,{key,name:r.name,clientCode:r.clientCode||'',region:regionOk(r.region),city:r.city||'',ibge:r.ibge||'',profile:r.profile||'',sales:0,lastBuy:r.lastBuy||'',record:r,rows:[]})}
    return [...grouped.values()].map(c=>({...c,marketMunicipality:mapMarket(c.city,'',c.ibge)||mapMarket(c.city,c.region.slice(0,2),c.ibge)})).filter(c=>c.marketMunicipality&&c.region)
  }
  function indexedSales(){return new Promise(resolve=>{if(!window.indexedDB){resolve([]);return}let req;try{req=indexedDB.open(SALES_DB,1)}catch{resolve([]);return}req.onerror=()=>resolve([]);req.onsuccess=()=>{const db=req.result;if(!db.objectStoreNames.contains(SALES_STORE)){db.close();resolve([]);return}try{const r=db.transaction(SALES_STORE,'readonly').objectStore(SALES_STORE).get(SALES_ID);r.onsuccess=()=>{const rows=r.result?.rows;db.close();resolve(Array.isArray(rows)?rows:[])};r.onerror=()=>{db.close();resolve([])}}catch{db.close();resolve([])}}})}
  async function refreshClients(){sales=Array.isArray(window.crmSalesData)?window.crmSalesData:await indexedSales();clients=loadClients();render()}
  function selectedRange(){const p=$('marketPeriod')?.value||'ytd26';let year,month;if(p==='ytd25')year=2025;else if(p==='ytd26'||p==='p:2026-YTD-09')year=2026;else{const k=p.slice(2);year=Number(k.slice(0,4));month=Number(k.slice(5,7));if(month)return{from:`${year}-${String(month).padStart(2,'0')}-01`,to:new Date(year,month,0).toISOString().slice(0,10)}}return{from:`${year}-01-01`,to:`${year}-09-30`}}
  function selectedClientRows(c){const range=selectedRange();return (c.rows||[]).filter(t=>t.date>=range.from&&t.date<=range.to&&!norm(t.operation).includes('devolucao')&&Number(t.value)>0)}
  function showClients(ibge){const m=marketByCode(ibge),period=$('marketPeriod').value,segment=$('marketSegment').value||'all',metric=m?segmentData(m,segment,period):{market:0,alta:0},share=metric.market?metric.alta/metric.market:0;const selectedSegment=$('marketSegment')?.value||'all',attached=clients.filter(c=>String(c.marketMunicipality.ibge)===String(ibge)&&(selectedSegment==='all'||(selectedSegment==='milk'?['LEITE','AMBOS'].includes(String(c.profile||'').toUpperCase()):['CORTE','AMBOS'].includes(String(c.profile||'').toUpperCase())))),title=m?`${m.city} · ${m.state}`:'Município';$('marketClientsTitle').textContent=`Clientes vinculados · ${title}`;$('marketClientCount').textContent=`${attached.length.toLocaleString('pt-BR')} clientes`;$('marketClientNote').textContent=`Market share municipal da Alta: ${pct(share*100)} · ${cash(metric.market)} doses totais ASBIA · ${cash(metric.alta)} doses Alta. Os clientes abaixo são contas cadastradas na carteira do município; esse share não é a quota individual de cada cliente.`;const body=$('marketClientRows');body.innerHTML=attached.length?attached.map(c=>{const periodRows=selectedClientRows(c),purchaseValue=periodRows.reduce((s,t)=>s+Number(t.value||0),0),bought=periodRows.length?'Sim':'Não identificado';const rec=c.record,phone=String(rec?.phone||'').replace(/\D/g,''),wa=phone.length>=10?`<a class="btn btn-small" target="_blank" rel="noopener" href="https://wa.me/${phone.startsWith('55')?phone:'55'+phone}">WhatsApp</a>`:'';return`<tr><td>${rec?`<button class="market-client-link" data-open-market-client="${esc(rec.id)}">${esc(c.name)}</button>`:`<b>${esc(c.name)}</b>`}<small class="catalog-flag">${esc(c.clientCode||'')}</small></td><td>${esc(c.region)}</td><td>${esc(c.profile||'—')}</td><td>${cash(purchaseValue)}</td><td>${esc(c.lastBuy||'—')}</td><td>${bought}</td><td>${wa}</td></tr>`}).join(''):'<tr><td colspan="7" class="analytics-empty">Nenhum cliente conciliado neste município. Confira município e código IBGE na base faturada ou no cadastro.</td></tr>';document.querySelector('.market-clients')?.scrollIntoView({behavior:'smooth',block:'start'})}
  function toast(message){const el=$('toast');if(!el)return;el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
  function showView(){ensureUI();document.querySelectorAll('.view-section').forEach(x=>x.classList.toggle('active',x.id==='marketShareView'));document.querySelectorAll('.nav button[data-view],.nav button[data-market-view],.nav button[data-dash-view],.nav button[data-weekly-view]').forEach(x=>x.classList.toggle('active',x.dataset.marketView==='marketShareView'));const crumb=$('crumbName');if(crumb)crumb.textContent='Market Share';$('sidebar')?.classList.remove('open');refreshClients()}
  function boot(){ensureUI();window.addEventListener('crm:sales-ready',refreshClients);window.addEventListener('crm:records-updated',refreshClients);window.addEventListener('storage',e=>{if(e.key===CRM_KEY||e.key===KEY)refreshClients()});document.addEventListener('click',e=>{const b=e.target.closest('[data-market-view="marketShareView"]');if(b){e.preventDefault();e.stopPropagation();showView()}});refreshClients()}
